import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Bell, Search, SlidersHorizontal } from 'lucide-react';
import { useApp } from '../context/AppContext';
import AppLayout from '../components/AppLayout';
import { FoodCardH, RestaurantCard, SectionHeader, C } from '../components/UI';
import { FOOD_ITEMS, RESTAURANTS, CATEGORIES } from '../data/mockData';

export default function HomeScreen() {
  const navigate = useNavigate();
  const { user } = useApp();
  const [activeCategory, setActiveCategory] = useState('all');
  const name = user?.name || 'Guest';

  const filtered = activeCategory === 'all'
    ? FOOD_ITEMS
    : FOOD_ITEMS.filter(f => f.category.toLowerCase() === activeCategory);

  return (
    <AppLayout>
      {/* Header */}
      <div style={{ padding: '20px 16px 12px', display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
        <div>
          <div style={{ fontSize: 20, fontWeight: 800, color: '#fff' }}>Hello, {name}! 👋</div>
        </div>
        <div style={{ display: 'flex', gap: 10, alignItems: 'center' }}>
          <button onClick={() => {}} style={{ background: '#1e1e1e', border: `1px solid ${C.border}`, borderRadius: '50%', width: 36, height: 36, display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer' }}>
            <Bell size={16} color="#ccc" />
          </button>
        </div>
      </div>

      {/* Search bar */}
      <div style={{ padding: '0 16px 16px' }}>
        <div
          onClick={() => navigate('/search')}
          style={{
            display: 'flex', alignItems: 'center', gap: 10,
            background: '#1e1e1e', border: `1px solid ${C.border}`,
            borderRadius: 12, padding: '12px 14px', cursor: 'pointer',
          }}
        >
          <Search size={16} color="#666" />
          <span style={{ fontSize: 14, color: '#555', flex: 1 }}>Search for food or restaurants...</span>
          <SlidersHorizontal size={16} color="#666" />
        </div>
      </div>

      {/* Categories */}
      <div style={{ padding: '0 16px 16px' }}>
        <SectionHeader title="Categories" onViewAll={() => {}} />
        <div style={{ display: 'flex', gap: 10, overflowX: 'auto', paddingBottom: 4 }}>
          {CATEGORIES.map(cat => (
            <button
              key={cat.id}
              onClick={() => setActiveCategory(cat.id)}
              style={{
                display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 4,
                padding: '10px 14px', borderRadius: 12, flexShrink: 0, cursor: 'pointer',
                background: activeCategory === cat.id ? C.orange : '#1e1e1e',
                border: `1px solid ${activeCategory === cat.id ? C.orange : C.border}`,
                transition: 'all 0.2s',
              }}
            >
              <span style={{ fontSize: 20 }}>{cat.emoji}</span>
              <span style={{ fontSize: 11, fontWeight: 600, color: activeCategory === cat.id ? '#fff' : '#888' }}>{cat.label}</span>
            </button>
          ))}
        </div>
      </div>

      {/* Recommended for You */}
      <div style={{ padding: '0 16px 16px' }}>
        <SectionHeader title="Recommended for You" onViewAll={() => navigate('/search')} />
        <div style={{ display: 'flex', gap: 12, overflowX: 'auto', paddingBottom: 4 }}>
          {filtered.slice(0, 5).map(food => <FoodCardH key={food.id} food={food} />)}
        </div>
      </div>

      {/* Nearby Restaurants */}
      <div style={{ padding: '0 16px 16px' }}>
        <SectionHeader title="Nearby Restaurants" onViewAll={() => navigate('/nearby')} />
        {RESTAURANTS.slice(0, 2).map(r => <RestaurantCard key={r.id} restaurant={r} compact />)}
      </div>
    </AppLayout>
  );
}
